function reached(s,ep,step,last){return ep<s.ep||ep===s.ep&&(s.step>step||s.step===step&&(step===0||last));}
function resolve(spec,c,t,seen){if(typeof spec==='string')return [spec,{},''];let i=spec.key?c[spec.key]??0:spec.tally?band(spec.tally,t):spec.fn(c,t,seen);i=Math.max(0,Math.min(spec.v.length-1,i|0));const v=spec.v[i];return Array.isArray(v)?[v[0],v[1],'~'+i]:[v,{},'~'+i];}
