function events(s,last,seen={}){const c={...(s.choices||{}),__p:pilotCode(s),__auto:(s.pilot?.took==='legacy'?[]:s.pilot?.auto||[]).join(',')},t=routedTallies(c),out=[];PHONE.forEach((chapter,ep)=>chapter.forEach(([contact,spec,step,opts={}],i)=>{if(!reached(s,ep,step,last))return;if(opts.when&&!opts.when(c,t,seen))return;const [text,extra,suffix]=resolve(spec,c,t,seen),{when,...rest}=opts;out.push({id:`${ep}:${i}${suffix}`,ep,step,contact,text,...rest,...extra});}));if(reached(s,0,0,last)&&(s.ep>0||s.step>0||last))out.push({id:'bill:0',ep:0,step:0,contact:'Maya',text:'Potongan ini sudah tersebar.|这张被裁过的截图传开了。',attachment:0});return out.sort((a,b)=>a.ep-b.ep||a.step-b.step);}
function active(s,last){const scene=Object.entries(scenes).find(([key,x])=>x.ep===s.ep&&s.step===x.step&&last);return scene?{key:scene[0],...scene[1]}:null;}
function segments(text,roles){let start=0,index=0;const out=[];for(const m of text.matchAll(/“[^”]*”/g)){if(m.index>start)out.push({role:'narration',text:text.slice(start,m.index)});out.push({role:roles[index++]||'narration',text:m[0]});start=m.index+m[0].length;}if(start<text.length)out.push({role:'narration',text:text.slice(start)});return out;}
